param([Parameter(Mandatory=$true)][string]$IncomingPath,[Parameter(Mandatory=$true)][string]$ExistingCrmPath,[string]$OutputPath="")
$ErrorActionPreference="Stop"
function E($v){([string]$v).Trim().ToLower()}
function P($v){$d=([string]$v-replace'\D','');if($d.Length-eq11-and$d.StartsWith("1")){$d=$d.Substring(1)};$d}
$i=Get-Content $IncomingPath -Raw|ConvertFrom-Json;$c=Get-Content $ExistingCrmPath -Raw|ConvertFrom-Json;$inc=if($i.records){@($i.records)}else{@($i)};$crm=if($c.leads){@($c.leads)}else{@($c)};$out=@()
foreach($l in $inc){$bs=0;$bm=$null;$br=@();foreach($x in $crm){$s=0;$r=@();if((E $l.PrimaryEmail)-and(E $l.PrimaryEmail)-eq(E $x.Email)){$s+=55;$r+="EMAIL_EXACT"};if((P $l.PrimaryPhone)-and(P $l.PrimaryPhone)-eq(P $x.Phone)){$s+=45;$r+="PHONE_EXACT"};if((E $l.PrimaryPropertyAddress)-and(E $l.PrimaryPropertyAddress)-eq(E $x.Address)){$s+=20;$r+="ADDRESS_EXACT"};if($s-gt$bs){$bs=$s;$bm=$x;$br=$r}};$action=if($bs-ge90){"MERGE_RECOMMENDED"}elseif($bs-ge60){"BROKER_REVIEW"}else{"NEW_LEAD_CANDIDATE"};$out+=[pscustomobject]@{MessageId=$l.MessageId;FirstName=$l.FirstName;LastName=$l.LastName;Email=$l.PrimaryEmail;Phone=$l.PrimaryPhone;PropertyAddress=$l.PrimaryPropertyAddress;MatchScore=$bs;MatchReasons=$br;Action=$action;ExistingLeadId=if($bm){[string]$bm.LeadId}else{""};ExistingAssignedTo=if($bm){[string]$bm.AssignedTo}else{""};PreserveExistingOwnership=[bool]($bm-and$bm.AssignedTo)}}
if(!$OutputPath){$OutputPath=Join-Path $PSScriptRoot "reports\LeadMergeCandidates.json"};@{release="MOS5-016-S1I";candidates=$out;previewOnly=$true;crmWritesEnabled=$false}|ConvertTo-Json -Depth 40|Set-Content $OutputPath;Write-Host "[PASS] Merge candidates: $($out.Count)"